import re
from collections import deque
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple


_SECTION_RE = re.compile(r"^\s*\[([^\]]+)\]\s*$")
_CHOICE_RE = re.compile(r"^\s*(\d+)\.\s*(.*?)\s*(?:->\s*([A-Za-z0-9_\-]+)\s*)?$")


@dataclass(frozen=True)
class Node:
    id: str
    text: str
    speaker: str
    type: str  # "line" | "choice"


@dataclass(frozen=True)
class Edge:
    from_: str
    to: str
    text: str


def _split_speaker_text(s: str) -> Tuple[str, str]:
    if ":" not in s:
        return "", s.strip()
    speaker, rest = s.split(":", 1)
    return speaker.strip(), rest.strip()


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    """Parse a dialogue script into a JSON-serializable graph.

    Output format:
      {"nodes":[{"id","text","speaker","type"}],
       "edges":[{"from","to","text"}]}
    """

    sections: Dict[str, List[str]] = {}
    order: List[str] = []

    current: Optional[str] = None
    for raw in text.splitlines():
        m = _SECTION_RE.match(raw)
        if m:
            current = m.group(1).strip()
            if current not in sections:
                sections[current] = []
                order.append(current)
            continue
        if current is None:
            continue
        line = raw.rstrip("\n")
        if not line.strip():
            continue
        sections[current].append(line.strip())

    if not order:
        return {"nodes": [], "edges": []}

    nodes_by_id: Dict[str, Node] = {}
    edges: List[Edge] = []

    # First pass: create nodes/edges for defined sections.
    for sid in order:
        lines = sections.get(sid, [])

        choice_lines: List[Tuple[str, str]] = []  # (choice_text, target)
        prompt_parts: List[str] = []
        prompt_speaker: str = ""

        for l in lines:
            cm = _CHOICE_RE.match(l)
            if cm and cm.group(1) is not None and l.lstrip()[0].isdigit():
                choice_text = (cm.group(2) or "").strip()
                target = (cm.group(3) or "").strip()
                if not target:
                    continue
                choice_lines.append((choice_text, target))
                continue

            if "->" in l:
                left, right = [p.strip() for p in l.rsplit("->", 1)]
                if right:
                    speaker, msg = _split_speaker_text(left)
                    if speaker and not prompt_speaker:
                        prompt_speaker = speaker
                    if msg:
                        prompt_parts.append(msg)
                else:
                    prompt_parts.append(left)
            else:
                prompt_parts.append(l.strip())

        if choice_lines:
            node_text = "\n".join([p for p in prompt_parts if p])
            nodes_by_id[sid] = Node(id=sid, text=node_text, speaker=prompt_speaker, type="choice")
            for ctext, target in choice_lines:
                edges.append(Edge(from_=sid, to=target, text=ctext))
            continue

        # Line node
        speaker = ""
        msg_parts: List[str] = []
        targets: List[str] = []
        for l in lines:
            if "->" in l:
                left, right = [p.strip() for p in l.rsplit("->", 1)]
                if right:
                    targets.append(right)
                sp, msg = _split_speaker_text(left)
                if sp and not speaker:
                    speaker = sp
                if msg:
                    msg_parts.append(msg)
                elif left:
                    msg_parts.append(left)
            else:
                sp, msg = _split_speaker_text(l)
                if sp and not speaker:
                    speaker = sp
                if msg:
                    msg_parts.append(msg)

        nodes_by_id[sid] = Node(id=sid, text="\n".join([p for p in msg_parts if p]), speaker=speaker, type="line")
        for t in targets:
            edges.append(Edge(from_=sid, to=t, text=""))

    # Second pass: ensure all targets exist (create placeholders, notably End).
    for e in list(edges):
        if e.to and e.to not in nodes_by_id:
            placeholder_text = "End" if e.to == "End" else ""
            nodes_by_id[e.to] = Node(id=e.to, text=placeholder_text, speaker="", type="line")

    # Reachability filter from first declared section.
    start = order[0]
    adj: Dict[str, List[str]] = {}
    for e in edges:
        adj.setdefault(e.from_, []).append(e.to)

    reachable: set[str] = set()
    q: deque[str] = deque([start])
    while q:
        n = q.popleft()
        if n in reachable:
            continue
        reachable.add(n)
        for nxt in adj.get(n, []):
            if nxt and nxt not in reachable:
                q.append(nxt)

    nodes = [nodes_by_id[nid] for nid in nodes_by_id.keys() if nid in reachable]
    node_ids = {n.id for n in nodes}
    filtered_edges = [e for e in edges if e.from_ in node_ids and e.to in node_ids]

    graph = {
        "nodes": [{"id": n.id, "text": n.text, "speaker": n.speaker, "type": n.type} for n in nodes],
        "edges": [{"from": e.from_, "to": e.to, "text": e.text} for e in filtered_edges],
    }

    _validate_graph(graph)
    return graph


def _validate_graph(graph: Dict[str, List[Dict[str, str]]]) -> None:
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])
    if not nodes:
        return

    node_ids = {n["id"] for n in nodes}

    # Edge targets must exist.
    for e in edges:
        if e.get("from") not in node_ids:
            raise ValueError(f"Edge from missing node: {e}")
        if e.get("to") not in node_ids:
            raise ValueError(f"Edge to missing node: {e}")

    # All nodes reachable from first node.
    start = nodes[0]["id"]
    adj: Dict[str, List[str]] = {}
    for e in edges:
        adj.setdefault(e["from"], []).append(e["to"])

    seen: set[str] = set()
    q: deque[str] = deque([start])
    while q:
        cur = q.popleft()
        if cur in seen:
            continue
        seen.add(cur)
        for nxt in adj.get(cur, []):
            if nxt not in seen:
                q.append(nxt)

    unreachable = sorted(node_ids - seen)
    if unreachable:
        raise ValueError(f"Unreachable nodes from {start}: {unreachable}")


def graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])

    def esc(s: str) -> str:
        return s.replace("\\", "\\\\").replace('"', '\\"')

    lines: List[str] = [
        "digraph Dialogue {",
        "  rankdir=LR;",
        "  node [fontname=Helvetica];",
    ]

    for n in nodes:
        nid = n["id"]
        ntype = n.get("type", "line")
        speaker = n.get("speaker", "")
        text = n.get("text", "")
        if ntype == "choice":
            shape = "diamond"
            label = f"{nid}" if not text else f"{nid}\\n{text}"
        else:
            shape = "box"
            if speaker and text:
                label = f"{speaker}: {text}"
            else:
                label = text or nid
        lines.append(f'  "{esc(nid)}" [shape={shape}, label="{esc(label)}"];')

    for e in edges:
        src = e["from"]
        dst = e["to"]
        etxt = e.get("text") or ""
        if etxt:
            lines.append(f'  "{esc(src)}" -> "{esc(dst)}" [label="{esc(etxt)}"];')
        else:
            lines.append(f'  "{esc(src)}" -> "{esc(dst)}";')

    lines.append("}")
    return "\n".join(lines) + "\n"


def main() -> None:
    script_path = "/app/script.txt"
    json_path = "/app/dialogue.json"
    dot_path = "/app/dialogue.dot"

    with open(script_path, "r", encoding="utf-8") as f:
        text = f.read()

    graph = parse_script(text)

    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(graph, f, ensure_ascii=False, indent=2)
        f.write("\n")

    with open(dot_path, "w", encoding="utf-8") as f:
        f.write(graph_to_dot(graph))


if __name__ == "__main__":
    main()
