    sections: Dict[str, List[str]] = {}
    order: List[str] = []

    current: Optional[str] = None
    for raw in text.splitlines():
        m = _SECTION_RE.match(raw)
        if m:
            current = m.group(1).strip()
            if current not in sections:
                sections[current] = []
                order.append(current)
            continue
        if current is None:
            continue
        line = raw.rstrip("\n")
        if not line.strip():
            continue
        sections[current].append(line.strip())

    if not order:
        return {"nodes": [], "edges": []}

    nodes_by_id: Dict[str, Node] = {}
    edges: List[Edge] = []

    # First pass: create nodes/edges for defined sections.
    for sid in order:
        lines = sections.get(sid, [])

        choice_lines: List[Tuple[str, str]] = []  # (choice_text, target)
        prompt_parts: List[str] = []
        prompt_speaker: str = ""

        for l in lines:
            cm = _CHOICE_RE.match(l)
            if cm and cm.group(1) is not None and l.lstrip()[0].isdigit():
                choice_text = (cm.group(2) or "").strip()
                target = (cm.group(3) or "").strip()
                if not target:
                    continue
                choice_lines.append((choice_text, target))
                continue

            if "->" in l:
                left, right = [p.strip() for p in l.rsplit("->", 1)]
                if right:
                    speaker, msg = _split_speaker_text(left)
                    if speaker and not prompt_speaker:
                        prompt_speaker = speaker
                    if msg:
                        prompt_parts.append(msg)
                else:
                    prompt_parts.append(left)
            else:
