            for ctext, target in choice_lines:
                edges.append(Edge(from_=sid, to=target, text=ctext))
            continue

        # Line node
        speaker = ""
        msg_parts: List[str] = []
        targets: List[str] = []
        for l in lines:
            if "->" in l:
                left, right = [p.strip() for p in l.rsplit("->", 1)]
                if right:
                    targets.append(right)
                sp, msg = _split_speaker_text(left)
                if sp and not speaker:
                    speaker = sp
                if msg:
                    msg_parts.append(msg)
                elif left:
                    msg_parts.append(left)
            else:
                sp, msg = _split_speaker_text(l)
                if sp and not speaker:
                    speaker = sp
                if msg:
                    msg_parts.append(msg)

        nodes_by_id[sid] = Node(id=sid, text="\n".join([p for p in msg_parts if p]), speaker=speaker, type="line")
