    return graph


def _validate_graph(graph: Dict[str, List[Dict[str, str]]]) -> None:
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])
    if not nodes:
        return

    node_ids = {n["id"] for n in nodes}

    # Edge targets must exist.
    for e in edges:
        if e.get("from") not in node_ids:
            raise ValueError(f"Edge from missing node: {e}")
        if e.get("to") not in node_ids:
            raise ValueError(f"Edge to missing node: {e}")

    # All nodes reachable from first node.
    start = nodes[0]["id"]
    adj: Dict[str, List[str]] = {}
    for e in edges:
        adj.setdefault(e["from"], []).append(e["to"])

    seen: set[str] = set()
    q: deque[str] = deque([start])
    while q:
        cur = q.popleft()
        if cur in seen:
            continue
        seen.add(cur)
        for nxt in adj.get(cur, []):
            if nxt not in seen:
                q.append(nxt)

    unreachable = sorted(node_ids - seen)
    if unreachable:
        raise ValueError(f"Unreachable nodes from {start}: {unreachable}")


def graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])

    def esc(s: str) -> str:
        return s.replace("\\", "\\\\").replace('"', '\\"')

    lines: List[str] = [
        "digraph Dialogue {",
        "  rankdir=LR;",
        "  node [fontname=Helvetica];",
    ]

    for n in nodes:
        nid = n["id"]
        ntype = n.get("type", "line")
        speaker = n.get("speaker", "")
        text = n.get("text", "")
        if ntype == "choice":
            shape = "diamond"
            label = f"{nid}" if not text else f"{nid}\\n{text}"
        else:
            shape = "box"
            if speaker and text:
